     * Scopes: campaigns:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/remove_failed_campaign_recipients_api_v1_campaigns__campaign_id__recipients_remove_failed_post
     */
    public function removeFailedRecipients(string $campaignId, ?string $idempotencyKey = null): RemoveFailedRecipients
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/recipients/remove-failed',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return RemoveFailedRecipients::fromArray($response->data());
    }

    /**
     * Delete Campaign Recipient.
     *
     * Remove a single recipient from a messenger/newsletter campaign.
     *
     * Hard-deletes the per-recipient row (tenant + campaign ownership validated), then recomputes the
     * campaign's denormalized counters and drops total_recipients by 1. A recipient who was already
     * sent the message (sent / delivered / read) cannot be removed: HTTP 409.
     *
     * Scopes: campaigns:update.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/delete_campaign_recipient_api_v1_campaigns__campaign_id__recipients__recipient_id__delete
     */
    public function deleteRecipient(string $campaignId, string $recipientId): Delete
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId),
        ));

        return Delete::fromArray($response->data());
    }

    /**
     * Retry Campaign Recipient.
     *
     * Retry a single failed recipient of a messenger/newsletter campaign.
     *
     * Calls the retry execution in CampaignService.retry_single_recipient and returns the updated
     * recipient item so the UI can update the row inline.
     *
     * - Recipient not found -> 404 - Recipient not retryable in its current state -> 409
     *
     * Scopes: campaigns:send.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/retry_campaign_recipient_api_v1_campaigns__campaign_id__recipients__recipient_id__retry_post
     */
    public function retryRecipient(
        string $campaignId,
        string $recipientId,
        ?string $idempotencyKey = null,
    ): CampaignRecipientItem {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId).'/retry',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return CampaignRecipientItem::fromArray($response->data());
    }

    /**
     * Unsubscribe Campaign Recipient.
     *
     * Opt a messenger/newsletter recipient's contact out of this campaign's lists.
     *
     * This is DISTINCT from DELETE /{campaign_id}/recipients/{recipient_id} ("Remove"), which only
     * deletes the per-recipient row and does NOT change subscription state. This endpoint resolves the
     * recipient's contact, computes the campaign's originating list(s) (campaign_lists ∩ the
     * contact's currently-subscribed lists) and opts the contact out of all of them via the
     * subscription chokepoint, writing the opt-out ledger with campaign attribution (method='manual').
     *
     * - Recipient (or its campaign) not found for this tenant -> 404 - Recipient is an anonymous
     * subscriber with no linked contact -> 422 - Contact subscribed to none of the campaign's lists
     * (or the campaign targets no lists) -> 200 with an empty unsubscribed_lists - Contact already
     * opted out of all of the campaign's lists -> 200 with already_unsubscribed: true
     *
     * Scopes: campaigns:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/unsubscribe_campaign_recipient_api_v1_campaigns__campaign_id__recipients__recipient_id__unsubscribe_post
     */
    public function unsubscribeRecipient(
        string $campaignId,
        string $recipientId,
        ?string $idempotencyKey = null,
    ): RecipientUnsubscribe {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId).'/unsubscribe',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return RecipientUnsubscribe::fromArray($response->data());
    }

    /**
     * Resume Campaign.
     *
     * Resume a paused or failed campaign
     *
     * For split-sending campaigns the remaining recipients are re-planned from now: today's batch is
     * sent, later batches continue on the following days.
     *
     * Optional body {"acknowledge_warmup_warning": true} (no body = false). A campaign the scheduler
     * paused with throttle_reason = "warmup_acknowledgement_required" (its warm-up acknowledgement was
     * missing or cleared by an edit), and any campaign resumed before its recipients were prepared,
     * passes the same WhatsApp warm-up gate as POST /send: HTTP 409 warmup_acknowledgement_required
     * unless acknowledged; nothing changes on 409. Such a campaign is then dispatched like a fresh
     * send (recipients prepared, day 1 of a split plan published). A campaign held because its
     * audience grew since the acknowledgement (warmup_assessment.hold.kind = "audience_grew") always
     * needs acknowledge_warmup_warning: true. A successful resume clears warmup_assessment.hold.
     *
     * Scopes: campaigns:send.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/resume_campaign_api_v1_campaigns__campaign_id__resume_post
     */
    public function resume(string $campaignId, ?array $body = null, ?string $idempotencyKey = null): Campaign
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/resume',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return Campaign::fromArray($response->data());
    }

    /**
     * Retry Failed Recipients.
     *
     * Retry failed recipients of a campaign
     *
     * Resets FAILED recipients back to pending and re-queues them for sending. Designed for "top up,
     * then retry": an SMS campaign that was paused because the prepaid SMS balance was used up can be
     * re-driven with {"error_codes": ["insufficient_sms_balance"]} once credit is available. SMS
     * recipients the carrier rejected or did not deliver are re-driven with {"error_codes":
     * ["sms_rejected_by_carrier"]} / ["sms_not_delivered"] (e.g. after the cause of an automatic pause
     * was fixed). SMS recipients that failed because the SMS provider temporarily limited the sending
     * rate are re-driven with {"error_codes": ["sms_rate_limited"]} -- lower the campaign's
     * send_rate_limit or set a send_batch_size first (PUT /campaigns/{id}) so the retry does not hit
     * the limit again. With no body (or an empty list) every failed recipient is retried. Unknown
     * codes return HTTP 422 listing the allowed codes.
     *
     * Allowed on campaigns in status completed, failed or paused. A completed or failed campaign
     * returns to sending and any recipients still pending are re-queued as well. A paused campaign
     * STAYS paused: the failed recipients are reset and go out together with the rest when the
     * campaign is resumed (POST /campaigns/{id}/resume). A retry never resumes a paused campaign.
     *
     * Scopes: campaigns:send.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     * @return array<array-key, mixed>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/retry_failed_recipients_api_v1_campaigns__campaign_id__retry_failed_post
     */
    public function retryFailedRecipients(
        string $campaignId,
        ?array $body = null,
        ?string $idempotencyKey = null,
    ): array {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/retry-failed',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return $response->data();
    }

    /**
     * Schedule Campaign.
     *
     * Schedule a campaign for future sending.
     *
     * Accepts a local datetime and IANA timezone string. The backend converts to UTC for storage. The
     * original timezone is preserved for display purposes.
     *
     * The scheduled time must be at least 5 minutes in the future.
     *
     * Scopes: campaigns:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/schedule_campaign_api_v1_campaigns__campaign_id__schedule_post
     */
    public function schedule(
        string $campaignId,
        DateTimeInterface|string $scheduledAt,
        string $timezone,
        ?bool $acknowledgeWarmupWarning = null,
        ?string $idempotencyKey = null,
    ): Campaign {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/schedule',
            body: Payload::body([
                'scheduled_at' => $scheduledAt,
                'timezone' => $timezone,
                'acknowledge_warmup_warning' => $acknowledgeWarmupWarning,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return Campaign::fromArray($response->data());
    }

