    /**
     * Send Campaign.
     *
     * Send a campaign immediately
     *
     * Optional body {"acknowledge_warmup_warning": true} (no body = false). A large WhatsApp campaign
     * on a number that is still warming up is refused with HTTP 409 detail = {"code":
     * "warmup_acknowledgement_required", "message": ..., "warmup": <warm-up assessment>} unless
     * acknowledged or split over days (send_split_config). Nothing is prepared or sent on 409. A split
     * plan that would run too long is refused with HTTP 422 {"code": "split_plan_too_long", "message":
     * ...}.
     *
     * With send_split_config, only day 1's batch is sent now; later batches go out automatically (the
     * response split block has days_total, next_batch_at, scheduled_count).
     *
     * Scopes: campaigns:send.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     * @return array<array-key, mixed>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/send_campaign_api_v1_campaigns__campaign_id__send_post
     */
    public function send(string $campaignId, ?array $body = null, ?string $idempotencyKey = null): array
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/send',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return $response->data();
    }

    /**
     * Send Next Batch.
     *
     * Send the next batch of a campaign sent in batches
     *
     * Only for a campaign that finished a batch: status = "paused" with throttle_reason =
     * "batch_complete", or one that ended as completed / failed while recipients were still waiting
     * (it continues its unfinished batch first, if any). Anything else returns HTTP 409 {"code":
     * "campaign_not_awaiting_batch", "message": ...} (also when two requests race: only the first one
     * sends a batch). HTTP 422 send_pacing_unavailable while batch sending is briefly unavailable.
     *
     * Body (optional): {"batch_size": 500} sends 500 recipients now and saves 500 as the campaign's
     * batch size (1-1,000,000; anything else is HTTP 422 {"code": "send_batch_size_invalid",
     * "message": ...}); {"all_remaining": true} sends everyone who is still waiting. An empty body
     * sends the next batch at the saved batch size. Recipients who opted out, unsubscribed or were
     * blocked since the campaign was prepared are skipped (skipped_ineligible).
     *
     * Scopes: campaigns:send.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/send_next_batch_api_v1_campaigns__campaign_id__send_next_batch_post
     */
    public function sendNextBatch(
        string $campaignId,
        ?array $body = null,
        ?string $idempotencyKey = null,
    ): SendNextBatch {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/campaigns/'.Payload::segment($campaignId).'/send-next-batch',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return SendNextBatch::fromArray($response->data());
    }

    /**
     * Get Campaign Send Plan.
     *
     * Send plan: speed, batches and estimated duration
     *
     * Read-only estimate for the campaign's audience at its saved send speed and batch size, or at the
     * values given as query parameters (to preview a change before saving it).
     * effective_rate_per_minute is the requested speed capped by what the campaign's channels can
     * send, and rate_limited_by says which of the two decides ("campaign" or "channel"). channels[]
     * lists each channel's recipients and maximum messages per second. eta_seconds estimates the time
     * to send everyone who is left (time paused between batches not included); eta_seconds_per_batch
     * the time per batch. pacing_available = false means send speed and batches are not available for
     * this account yet.
     *
     * Out-of-range query values return HTTP 422 {code, message} (send_rate_limit_out_of_range,
     * send_batch_size_invalid).
     *
     * Scopes: campaigns:read.
     *
     * @param  ?int  $sendRateLimit  Preview this send speed (messages per minute, 1-60000) instead of the saved one
     * @param  ?int  $sendBatchSize  Preview this batch size (>= 1) instead of the saved one
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/get_campaign_send_plan_api_v1_campaigns__campaign_id__send_plan_get
     */
    public function getSendPlan(string $campaignId, ?int $sendRateLimit = null, ?int $sendBatchSize = null): SendPlan
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/campaigns/'.Payload::segment($campaignId).'/send-plan',
            query: Payload::query(['send_rate_limit' => $sendRateLimit, 'send_batch_size' => $sendBatchSize]),
        ));

        return SendPlan::fromArray($response->data());
    }

