    /**
     * Get Campaign Unsubscribes.
     *
     * List recipients who opted out attributed to THIS messenger campaign.
     *
     * Campaign-attributed opt-outs from the contact_subscription_events SHARD ledger, split by source
     * and confidence:
     *
     * * LINK opt-outs (method='link', attribution='exact') — recipient used this campaign's own
     * unsubscribe surface; attribution is certain. * KEYWORD opt-outs (method='keyword',
     * attribution='heuristic') — a "stop"-style keyword opt-out attributed to the last campaign on
     * that channel within window_hours. Only keyword opt-outs the heuristic matched to THIS campaign
     * appear here.
     *
     * Scopes: campaigns:read.
     *
     * @return Page<AppSchemasCampaignSchemaCampaignUnsubscribeItem>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Campaigns/get_campaign_unsubscribes_api_v1_campaigns__campaign_id__unsubscribes_get
     */
    public function getUnsubscribes(string $campaignId, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/campaigns/'.Payload::segment($campaignId).'/unsubscribes',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), AppSchemasCampaignSchemaCampaignUnsubscribeItem::fromArray(...), fn (int $page): Page => $this->getUnsubscribes(campaignId: $campaignId, page: $page, pageSize: $pageSize));
    }
}
